-- EDUBRIDGE 1.9 – original starter learning library; no scanned textbook reproduction and no Gemini calls.
create table if not exists public.edubridge_ready_lessons (
 id uuid primary key default gen_random_uuid(),
 slug text not null unique,
 subject text not null,
 grade text not null check(grade in ('10','11','12')),
 sort_order integer not null default 1,
 chapter text not null default '',
 title text not null check(char_length(title) between 5 and 180),
 source_text text not null check(char_length(source_text) between 250 and 30000),
 material_type text not null default 'original_reference' check(material_type='original_reference'),
 is_active boolean not null default true,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create index if not exists edubridge_ready_lookup on public.edubridge_ready_lessons(subject,grade,sort_order) where is_active;
alter table public.edubridge_ready_lessons enable row level security;
drop policy if exists edubridge_read_ready_lessons on public.edubridge_ready_lessons;
create policy edubridge_read_ready_lessons on public.edubridge_ready_lessons for select to authenticated
 using (is_active and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('teacher','admin')));
revoke all on public.edubridge_ready_lessons from public,anon,authenticated;
grant select on public.edubridge_ready_lessons to authenticated;
grant all on public.edubridge_ready_lessons to service_role;
-- Seed is idempotent: updates the original EDUBRIDGE lesson content, leaves teacher work and SGK review untouched.
insert into public.edubridge_ready_lessons(slug,subject,grade,sort_order,chapter,title,source_text)
select slug,subject,grade,sort_order,chapter,title,source_text
from jsonb_to_recordset($original_edubridge$[{"subject":"Vật lí","grade":"12","sort_order":1,"chapter":"Chương I. Vật lí nhiệt","title":"Bài 1. Cấu trúc của chất. Sự chuyển thể","slug":"physics12-01","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 1. Cấu trúc của chất. Sự chuyển thể. Chương I. Vật lí nhiệt.\nKiến thức cốt lõi: Các chất gồm những hạt cấu tạo chuyển động nhiệt không ngừng, tương tác với nhau. Rắn có trật tự sắp xếp tương đối ổn định; lỏng có thể tích tương đối xác định, dễ đổi hình dạng; khí chiếm thể tích bình chứa. Sự nóng chảy, đông đặc, bay hơi, ngưng tụ và sôi là các quá trình chuyển thể; nhiệt lượng cung cấp có thể làm thay đổi trạng thái thay vì làm tăng nhiệt độ.\nThuật ngữ song ngữ gợi ý: particle – hạt; state of matter – trạng thái vật chất; melting – nóng chảy; evaporation – bay hơi.\nHoạt động và đánh giá gợi ý: Quan sát nước đá tan và nước bốc hơi; chỉ ra điểm khác biệt giữa sôi và bay hơi. Vì sao quần áo vẫn khô khi trời lạnh?\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":2,"chapter":"Chương I. Vật lí nhiệt","title":"Bài 2. Nội năng. Định luật I của nhiệt động lực học","slug":"physics12-02","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 2. Nội năng. Định luật I của nhiệt động lực học. Chương I. Vật lí nhiệt.\nKiến thức cốt lõi: Nội năng là tổng động năng chuyển động nhiệt và thế năng tương tác của các phân tử. Nội năng thay đổi do thực hiện công hoặc truyền nhiệt. Theo quy ước thường dùng: ΔU = Q + A, trong đó Q là nhiệt lượng hệ nhận, A là công ngoại lực thực hiện lên hệ; cần thống nhất dấu trước khi tính. Trong hệ cô lập, năng lượng không tự sinh ra hay mất đi.\nThuật ngữ song ngữ gợi ý: internal energy – nội năng; heat – nhiệt lượng; work – công; energy conservation – bảo toàn năng lượng.\nHoạt động và đánh giá gợi ý: Giải thích vì sao bơm xe nóng lên khi nén khí. Nhận diện dấu của Q và A trong một tình huống.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":3,"chapter":"Chương I. Vật lí nhiệt","title":"Bài 3. Nhiệt độ. Thang nhiệt độ – nhiệt kế","slug":"physics12-03","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 3. Nhiệt độ. Thang nhiệt độ – nhiệt kế. Chương I. Vật lí nhiệt.\nKiến thức cốt lõi: Nhiệt độ biểu thị mức độ nóng lạnh của vật và liên hệ với chuyển động nhiệt của các hạt. Thang Celsius và Kelvin dùng trong đo lường: T(K) = t(°C) + 273,15. Nhiệt kế hoạt động dựa trên đại lượng vật lí phụ thuộc nhiệt độ như thể tích chất lỏng hay điện trở. Hai vật cân bằng nhiệt không còn trao đổi nhiệt ròng với nhau.\nThuật ngữ song ngữ gợi ý: temperature – nhiệt độ; thermometer – nhiệt kế; thermal equilibrium – cân bằng nhiệt.\nHoạt động và đánh giá gợi ý: Chuyển đổi 25 °C sang Kelvin; nêu lí do không được đưa nhiệt kế vượt phạm vi đo.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":4,"chapter":"Chương I. Vật lí nhiệt","title":"Bài 4. Nhiệt dung riêng","slug":"physics12-04","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 4. Nhiệt dung riêng. Chương I. Vật lí nhiệt.\nKiến thức cốt lõi: Nhiệt dung riêng c đặc trưng cho nhiệt lượng cần để làm tăng nhiệt độ một đơn vị của một đơn vị khối lượng chất trong điều kiện xác định. Khi không có chuyển thể và c xem như không đổi: Q = mcΔT, trong đó ΔT là độ tăng nhiệt độ; nếu vật tỏa nhiệt, Q có thể lấy giá trị âm theo quy ước. Đơn vị SI của c là J/(kg·K). Cần phân biệt nhiệt dung và nhiệt dung riêng.\nThuật ngữ song ngữ gợi ý: specific heat capacity – nhiệt dung riêng; mass – khối lượng; temperature change – độ biến thiên nhiệt độ.\nHoạt động và đánh giá gợi ý: So sánh sự thay đổi nhiệt độ của nước và kim loại khi cùng nhận nhiệt lượng, cùng khối lượng.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":5,"chapter":"Chương I. Vật lí nhiệt","title":"Bài 5. Nhiệt nóng chảy riêng","slug":"physics12-05","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 5. Nhiệt nóng chảy riêng. Chương I. Vật lí nhiệt.\nKiến thức cốt lõi: Trong quá trình nóng chảy ở nhiệt độ chuyển thể, nhiệt lượng nhận chủ yếu làm thay đổi trạng thái mà không làm tăng nhiệt độ của lượng chất đang nóng chảy. Công thức gần đúng Q = λm, với λ là nhiệt nóng chảy riêng (J/kg) và m là khối lượng chuyển thể. Phải tách nhiệt lượng làm tăng nhiệt độ trước chuyển thể và nhiệt lượng nóng chảy nếu bài toán gồm nhiều giai đoạn.\nThuật ngữ song ngữ gợi ý: specific latent heat of fusion – nhiệt nóng chảy riêng; fusion – nóng chảy; phase transition – chuyển thể.\nHoạt động và đánh giá gợi ý: Tính nhiệt lượng cần để làm tan một lượng băng đã ở đúng nhiệt độ nóng chảy, biết λ.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":6,"chapter":"Chương I. Vật lí nhiệt","title":"Bài 6. Nhiệt hoá hơi riêng","slug":"physics12-06","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 6. Nhiệt hoá hơi riêng. Chương I. Vật lí nhiệt.\nKiến thức cốt lõi: Hóa hơi là quá trình chất chuyển từ lỏng sang khí. Khi chất lỏng hóa hơi ở điều kiện xét, có thể dùng Q = Lm để xác định nhiệt lượng cần cung cấp; L là nhiệt hóa hơi riêng (J/kg). Phân biệt bay hơi trên mặt thoáng có thể xảy ra ở nhiều nhiệt độ và sôi xảy ra trong toàn khối khi đạt điều kiện sôi. Giá trị L phụ thuộc chất và điều kiện.\nThuật ngữ song ngữ gợi ý: specific latent heat of vaporization – nhiệt hóa hơi riêng; boiling – sôi; condensation – ngưng tụ.\nHoạt động và đánh giá gợi ý: Vì sao sự bay hơi mồ hôi làm mát cơ thể? Phân biệt nhiệt làm nóng nước và nhiệt làm nước hóa hơi.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":7,"chapter":"Chương I. Vật lí nhiệt","title":"Bài 7. Bài tập về vật lí nhiệt","slug":"physics12-07","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 7. Bài tập về vật lí nhiệt. Chương I. Vật lí nhiệt.\nKiến thức cốt lõi: Khi giải bài toán nhiệt cần xác định từng giai đoạn: tăng hoặc giảm nhiệt độ, nóng chảy, đông đặc, hóa hơi và ngưng tụ. Tính Q = mcΔT cho giai đoạn không chuyển thể; Q = λm hoặc Q = Lm cho giai đoạn chuyển thể tương ứng. Nếu coi hệ cách nhiệt, nhiệt lượng các vật trao đổi thỏa điều kiện tổng đại số bằng 0. Ghi rõ giả thiết bỏ qua thất thoát và đơn vị.\nThuật ngữ song ngữ gợi ý: heat balance – cân bằng nhiệt; thermal process – quá trình nhiệt; phase change – chuyển pha.\nHoạt động và đánh giá gợi ý: Lập sơ đồ các giai đoạn khi nung nước đá thành hơi nước; chỉ ra công thức áp dụng ở mỗi giai đoạn.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":8,"chapter":"Chương II. Khí lí tưởng","title":"Bài 8. Mô hình động học phân tử chất khí","slug":"physics12-08","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 8. Mô hình động học phân tử chất khí. Chương II. Khí lí tưởng.\nKiến thức cốt lõi: Khí gồm rất nhiều phân tử chuyển động hỗn loạn và liên tục va chạm với nhau và thành bình. Trong mô hình khí lí tưởng đơn giản, kích thước phân tử coi là rất nhỏ so với khoảng cách giữa chúng và bỏ qua tương tác trừ khi va chạm. Áp suất khí có nguồn gốc từ các va chạm lên thành bình; nhiệt độ tuyệt đối liên quan tới động năng trung bình của chuyển động phân tử.\nThuật ngữ song ngữ gợi ý: kinetic molecular theory – thuyết động học phân tử; collision – va chạm; gas pressure – áp suất khí.\nHoạt động và đánh giá gợi ý: Vì sao khí chiếm toàn bộ bình chứa? Mô tả sự thay đổi va chạm phân tử khi khí nóng lên.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":9,"chapter":"Chương II. Khí lí tưởng","title":"Bài 9. Định luật Boyle","slug":"physics12-09","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 9. Định luật Boyle. Chương II. Khí lí tưởng.\nKiến thức cốt lõi: Đối với lượng khí xác định ở nhiệt độ không đổi, áp suất tỉ lệ nghịch với thể tích trong phạm vi mô hình khí lí tưởng: pV = hằng số; suy ra p1V1 = p2V2. Quá trình này gọi là đẳng nhiệt. Khi thể tích giảm, áp suất tăng nếu những yếu tố khác không đổi. Cần phân biệt điều kiện đẳng nhiệt với các quá trình có trao đổi nhiệt phức tạp.\nThuật ngữ song ngữ gợi ý: Boyle's law – định luật Boyle; isothermal process – quá trình đẳng nhiệt; pressure – áp suất.\nHoạt động và đánh giá gợi ý: Dự đoán áp suất khi nén một lượng khí từ 2 lít còn 1 lít ở cùng nhiệt độ.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":10,"chapter":"Chương II. Khí lí tưởng","title":"Bài 10. Định luật Charles","slug":"physics12-10","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 10. Định luật Charles. Chương II. Khí lí tưởng.\nKiến thức cốt lõi: Đối với một lượng khí xác định ở áp suất không đổi, thể tích tỉ lệ thuận với nhiệt độ tuyệt đối theo mô hình khí lí tưởng: V/T = hằng số; V1/T1 = V2/T2. Nhiệt độ T phải đo bằng Kelvin, không thay trực tiếp số °C vào tỉ số. Quá trình có áp suất không đổi gọi là đẳng áp. Chất khí thực chỉ xấp xỉ mô hình lí tưởng trong những điều kiện thích hợp.\nThuật ngữ song ngữ gợi ý: Charles's law – định luật Charles; isobaric process – quá trình đẳng áp; absolute temperature – nhiệt độ tuyệt đối.\nHoạt động và đánh giá gợi ý: Bóng bay biến đổi thể tích thế nào khi nhiệt độ tăng từ 300 K lên 330 K và áp suất không đổi?\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":11,"chapter":"Chương II. Khí lí tưởng","title":"Bài 11. Phương trình trạng thái của khí lí tưởng","slug":"physics12-11","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 11. Phương trình trạng thái của khí lí tưởng. Chương II. Khí lí tưởng.\nKiến thức cốt lõi: Khi lượng chất khí không đổi, mối liên hệ giữa áp suất, thể tích và nhiệt độ là pV/T = hằng số. Với n mol khí lí tưởng: pV = nRT, trong đó R là hằng số khí lí tưởng. Các đại lượng phải thống nhất đơn vị: p (Pa), V (m³), T (K), n (mol). Trước khi giải cần kiểm tra khí có thay đổi số mol hay không và điều kiện sử dụng mô hình.\nThuật ngữ song ngữ gợi ý: ideal gas equation – phương trình khí lí tưởng; amount of substance – lượng chất; molar gas constant – hằng số khí.\nHoạt động và đánh giá gợi ý: Dùng pV = nRT xác định một đại lượng còn thiếu và đổi đơn vị lít sang m³.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":12,"chapter":"Chương II. Khí lí tưởng","title":"Bài 12. Áp suất khí theo mô hình động học phân tử. Quan hệ giữa động năng phân tử và nhiệt độ","slug":"physics12-12","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 12. Áp suất khí theo mô hình động học phân tử. Quan hệ giữa động năng phân tử và nhiệt độ. Chương II. Khí lí tưởng.\nKiến thức cốt lõi: Va chạm của các phân tử lên thành bình tạo nên áp suất khí. Theo mô hình khí lí tưởng đơn nguyên tử ở cân bằng nhiệt, động năng tịnh tiến trung bình một phân tử là (3/2)kBT; kB là hằng số Boltzmann. Tăng nhiệt độ tuyệt đối làm tăng động năng tịnh tiến trung bình. Áp suất liên quan tới mật độ phân tử và bình phương vận tốc đặc trưng; không suy từ một phân tử riêng lẻ.\nThuật ngữ song ngữ gợi ý: average kinetic energy – động năng trung bình; Boltzmann constant – hằng số Boltzmann; molecular speed – tốc độ phân tử.\nHoạt động và đánh giá gợi ý: Hai mẫu khí có cùng nhiệt độ nhưng khác loại phân tử có động năng tịnh tiến trung bình bằng nhau không?\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":13,"chapter":"Chương II. Khí lí tưởng","title":"Bài 13. Bài tập về khí lí tưởng","slug":"physics12-13","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 13. Bài tập về khí lí tưởng. Chương II. Khí lí tưởng.\nKiến thức cốt lõi: Trước khi tính, xác định lượng khí có đổi không và quá trình là đẳng nhiệt, đẳng áp hay biến đổi tổng quát. Có thể dùng p1V1/T1 = p2V2/T2 nếu lượng khí không đổi, hoặc pV = nRT nếu biết số mol. Chuyển mọi nhiệt độ về Kelvin, đổi thể tích sang m³ và kiểm tra tính hợp lí của kết quả. Không dùng định luật Boyle khi nhiệt độ không giữ nguyên.\nThuật ngữ song ngữ gợi ý: gas laws – các định luật khí; state variables – thông số trạng thái; unit conversion – đổi đơn vị.\nHoạt động và đánh giá gợi ý: Lập bảng p, V, T hai trạng thái của khí; tìm đại lượng chưa biết và nhận xét chiều biến thiên.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":14,"chapter":"Chương III. Từ trường","title":"Bài 14. Từ trường","slug":"physics12-14","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 14. Từ trường. Chương III. Từ trường.\nKiến thức cốt lõi: Từ trường tồn tại quanh nam châm và dòng điện, biểu hiện qua tác dụng lực từ lên kim nam châm hoặc dòng điện. Cảm ứng từ B đặc trưng tác dụng từ tại điểm đang xét, có đơn vị tesla (T). Đường sức từ có hướng; tiếp tuyến với đường sức thể hiện hướng của vectơ B. Cần phân biệt đường biểu diễn hình học và vật thể thực.\nThuật ngữ song ngữ gợi ý: magnetic field – từ trường; magnetic flux density – cảm ứng từ; field line – đường sức từ.\nHoạt động và đánh giá gợi ý: Dùng la bàn khảo sát từ trường quanh một nam châm thẳng; vẽ chiều đường sức bên ngoài nam châm.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":15,"chapter":"Chương III. Từ trường","title":"Bài 15. Lực từ tác dụng lên dây dẫn mang dòng điện. Cảm ứng từ","slug":"physics12-15","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 15. Lực từ tác dụng lên dây dẫn mang dòng điện. Cảm ứng từ. Chương III. Từ trường.\nKiến thức cốt lõi: Dây dẫn có dòng điện trong từ trường chịu lực từ; khi dây thẳng dài l nằm trong từ trường đều, độ lớn lực F = BIl sinθ, θ là góc giữa chiều dòng điện và B. Lực vuông góc với phương dòng điện và phương cảm ứng từ. Dùng quy tắc xác định chiều lực thích hợp và kiểm tra hệ quy chiếu. Không dùng công thức đơn giản khi trường không đều hoặc dây cong mà không chia nhỏ.\nThuật ngữ song ngữ gợi ý: magnetic force – lực từ; electric current – dòng điện; magnetic induction – cảm ứng từ.\nHoạt động và đánh giá gợi ý: So sánh lực từ khi dây song song và vuông góc đường sức từ; giải thích khi nào lực bằng 0.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":16,"chapter":"Chương III. Từ trường","title":"Bài 16. Từ thông. Hiện tượng cảm ứng điện từ","slug":"physics12-16","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 16. Từ thông. Hiện tượng cảm ứng điện từ. Chương III. Từ trường.\nKiến thức cốt lõi: Từ thông qua một mặt phẳng diện tích S trong từ trường đều có độ lớn đại số Φ = BS cosθ theo quy ước pháp tuyến của mặt. Khi từ thông qua mạch thay đổi theo thời gian, xuất hiện suất điện động cảm ứng; chiều dòng cảm ứng tuân theo định luật Lenz, chống lại nguyên nhân gây biến thiên từ thông. Định luật Faraday cho suất điện động cảm ứng liên hệ tốc độ biến thiên từ thông.\nThuật ngữ song ngữ gợi ý: magnetic flux – từ thông; electromagnetic induction – cảm ứng điện từ; induced electromotive force – suất điện động cảm ứng.\nHoạt động và đánh giá gợi ý: Di chuyển nam châm ra vào cuộn dây nối điện kế và mô tả chiều biến thiên số chỉ.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":17,"chapter":"Chương III. Từ trường","title":"Bài 17. Máy phát điện xoay chiều","slug":"physics12-17","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 17. Máy phát điện xoay chiều. Chương III. Từ trường.\nKiến thức cốt lõi: Máy phát điện xoay chiều biến đổi cơ năng thành điện năng nhờ cảm ứng điện từ. Khi từ thông qua cuộn dây biến thiên tuần hoàn, suất điện động có thể biến thiên dạng hình sin trong mô hình lí tưởng. Một máy phát gồm bộ phận tạo từ trường và bộ phận có suất điện động cảm ứng; tùy cấu tạo, cuộn dây hoặc nam châm có thể quay. Hiệu suất không đạt 100% vì tổn hao.\nThuật ngữ song ngữ gợi ý: alternating current generator – máy phát xoay chiều; rotor – rôto; stator – stato; mechanical energy – cơ năng.\nHoạt động và đánh giá gợi ý: Mô tả chuỗi chuyển hóa năng lượng từ tua-bin quay đến điện năng ra mạch ngoài.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":18,"chapter":"Chương III. Từ trường","title":"Bài 18. Ứng dụng hiện tượng cảm ứng điện từ","slug":"physics12-18","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 18. Ứng dụng hiện tượng cảm ứng điện từ. Chương III. Từ trường.\nKiến thức cốt lõi: Cảm ứng điện từ được ứng dụng trong biến áp, bếp từ, sạc không dây và các thiết bị phát điện. Biến áp hoạt động với từ thông biến thiên, cho phép thay đổi điện áp xoay chiều trong giới hạn thiết kế. Bếp từ làm xuất hiện dòng điện cảm ứng trong dụng cụ nấu phù hợp, gây tỏa nhiệt. Với thiết bị thực phải xét tổn hao và quy tắc an toàn điện.\nThuật ngữ song ngữ gợi ý: transformer – máy biến áp; induction cooker – bếp từ; wireless charging – sạc không dây.\nHoạt động và đánh giá gợi ý: Vì sao máy biến áp không hoạt động như dự kiến với nguồn một chiều không đổi?\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":19,"chapter":"Chương III. Từ trường","title":"Bài 19. Điện từ trường. Mô hình sóng điện từ","slug":"physics12-19","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 19. Điện từ trường. Mô hình sóng điện từ. Chương III. Từ trường.\nKiến thức cốt lõi: Điện trường biến thiên theo thời gian có liên hệ với từ trường biến thiên; sự lan truyền của nhiễu loạn điện từ trong không gian tạo thành sóng điện từ. Trong chân không, sóng truyền với tốc độ c xấp xỉ 3,00×10^8 m/s. Vectơ điện trường và từ trường biến thiên vuông góc với nhau và với hướng truyền đối với sóng phẳng. Ánh sáng là một dạng sóng điện từ.\nThuật ngữ song ngữ gợi ý: electromagnetic wave – sóng điện từ; electric field – điện trường; wavelength – bước sóng.\nHoạt động và đánh giá gợi ý: Liên hệ tần số, bước sóng và tốc độ truyền; lấy ví dụ vô tuyến, ánh sáng nhìn thấy.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":20,"chapter":"Chương III. Từ trường","title":"Bài 20. Bài tập về từ trường","slug":"physics12-20","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 20. Bài tập về từ trường. Chương III. Từ trường.\nKiến thức cốt lõi: Phân loại bài toán: nhận biết chiều từ trường; lực từ trên dây dẫn; từ thông và suất điện động cảm ứng; ứng dụng thiết bị. Khi dùng F = BIl sinθ và Φ = BS cosθ, phải xác định đúng góc, chiều pháp tuyến và đơn vị. Với hiện tượng cảm ứng, xem đại lượng nào biến thiên theo thời gian và dùng định luật Lenz để suy chiều dòng. Mỗi kết quả cần được đối chiếu vật lí.\nThuật ngữ song ngữ gợi ý: magnetic field problems – bài toán từ trường; flux change – biến thiên từ thông; sign convention – quy ước dấu.\nHoạt động và đánh giá gợi ý: Phân tích hình nam châm – cuộn dây; nêu điều kiện xuất hiện dòng cảm ứng và cách xác định chiều.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":21,"chapter":"Chương IV. Vật lí hạt nhân","title":"Bài 21. Cấu trúc hạt nhân","slug":"physics12-21","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 21. Cấu trúc hạt nhân. Chương IV. Vật lí hạt nhân.\nKiến thức cốt lõi: Hạt nhân nguyên tử chứa proton mang điện dương và neutron không mang điện. Số proton Z xác định nguyên tố; số khối A bằng tổng số proton và neutron, nên N = A − Z. Các đồng vị cùng Z nhưng khác số neutron. Khối lượng hạt nhân thường biểu diễn theo đơn vị u; kí hiệu hạt nhân cần phân biệt số khối và số hiệu nguyên tử.\nThuật ngữ song ngữ gợi ý: atomic nucleus – hạt nhân; proton – proton; neutron – neutron; isotope – đồng vị.\nHoạt động và đánh giá gợi ý: Xác định số proton, neutron của một hạt nhân biết kí hiệu gồm A và Z.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":22,"chapter":"Chương IV. Vật lí hạt nhân","title":"Bài 22. Phản ứng hạt nhân và năng lượng liên kết","slug":"physics12-22","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 22. Phản ứng hạt nhân và năng lượng liên kết. Chương IV. Vật lí hạt nhân.\nKiến thức cốt lõi: Năng lượng liên kết hạt nhân liên hệ độ hụt khối thông qua E = Δmc²; năng lượng liên kết riêng là năng lượng liên kết chia số nucleon. Trong phản ứng hạt nhân, bảo toàn điện tích, số nucleon và năng lượng toàn phần. Năng lượng phản ứng Q được xác định từ chênh lệch khối lượng nghỉ trước và sau phản ứng, với dấu dương cho phản ứng tỏa năng lượng theo quy ước. Không nhầm bảo toàn tổng khối lượng nghỉ với bảo toàn năng lượng.\nThuật ngữ song ngữ gợi ý: binding energy – năng lượng liên kết; mass defect – độ hụt khối; nuclear reaction – phản ứng hạt nhân.\nHoạt động và đánh giá gợi ý: Kiểm tra cân bằng số khối A và điện tích Z trong phương trình phản ứng đơn giản.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":23,"chapter":"Chương IV. Vật lí hạt nhân","title":"Bài 23. Hiện tượng phóng xạ","slug":"physics12-23","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 23. Hiện tượng phóng xạ. Chương IV. Vật lí hạt nhân.\nKiến thức cốt lõi: Phóng xạ là sự biến đổi tự phát của một số hạt nhân không bền, phát ra bức xạ ion hóa. Các dạng điển hình gồm alpha, beta và gamma, có khả năng xuyên thấu và tác dụng ion hóa khác nhau. Số hạt chưa phân rã tuân định luật N = N0e^(−λt); chu kì bán rã T1/2 = ln2/λ. Hoạt độ A = λN có đơn vị becquerel (Bq). Cần tuân thủ quy tắc an toàn bức xạ.\nThuật ngữ song ngữ gợi ý: radioactivity – phóng xạ; half-life – chu kì bán rã; activity – hoạt độ; shielding – che chắn.\nHoạt động và đánh giá gợi ý: Sau hai chu kì bán rã, phần còn lại của lượng hạt nhân ban đầu là bao nhiêu?\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":24,"chapter":"Chương IV. Vật lí hạt nhân","title":"Bài 24. Công nghiệp hạt nhân","slug":"physics12-24","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 24. Công nghiệp hạt nhân. Chương IV. Vật lí hạt nhân.\nKiến thức cốt lõi: Kĩ thuật hạt nhân có ứng dụng trong phát điện, y học, công nghiệp và nghiên cứu. Lò phản ứng phân hạch được kiểm soát để tạo nhiệt, sau đó chuyển thành điện năng qua chu trình nhiệt. Ứng dụng đồng vị phóng xạ có thể dùng đánh dấu hoặc đo kiểm, nhưng phải tuân thủ thiết kế an toàn, quản lí chất thải và kiểm soát liều. Phân biệt nguyên lí vật lí với đánh giá lợi ích, rủi ro kinh tế – môi trường.\nThuật ngữ song ngữ gợi ý: nuclear power – điện hạt nhân; fission – phân hạch; radiation protection – bảo vệ bức xạ.\nHoạt động và đánh giá gợi ý: Lập bảng lợi ích và yêu cầu an toàn khi sử dụng kĩ thuật hạt nhân trong y học và năng lượng.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."},{"subject":"Vật lí","grade":"12","sort_order":25,"chapter":"Chương IV. Vật lí hạt nhân","title":"Bài 25. Bài tập về vật lí hạt nhân","slug":"physics12-25","source_text":"HỌC LIỆU EDUBRIDGE BIÊN SOẠN ĐỘC LẬP – KHÔNG PHẢI TRÍCH NGUYÊN VĂN SGK.\nChủ đề: Bài 25. Bài tập về vật lí hạt nhân. Chương IV. Vật lí hạt nhân.\nKiến thức cốt lõi: Bài tập hạt nhân yêu cầu xác định đúng Z, A, số neutron, đồng vị; cân bằng phản ứng theo A và Z; tính độ hụt khối, năng lượng liên kết qua E = Δmc²; và tính chu kì bán rã bằng tỉ lệ N/N0 = (1/2)^(t/T1/2). Các đại lượng phải được đổi về hệ đơn vị tương thích; nếu dùng u và MeV phải nêu quy đổi. Không tự suy kết quả số khi thiếu khối lượng hạt hoặc dữ liệu đề.\nThuật ngữ song ngữ gợi ý: nuclear physics problems – bài tập vật lí hạt nhân; mass-energy equivalence – tương đương khối lượng–năng lượng.\nHoạt động và đánh giá gợi ý: Tự thiết kế bài tính phần hạt còn lại sau 3 chu kì bán rã và một bài cân bằng phản ứng hạt nhân.\nGhi chú hậu kiểm: Đây là đề cương tham khảo do EDUBRIDGE biên soạn; giáo viên cần đối chiếu chương trình, sách đang dạy, công thức và phạm vi kiến thức trước khi sử dụng chính thức."}]
$original_edubridge$::jsonb)
as x(slug text,subject text,grade text,sort_order integer,chapter text,title text,source_text text)
on conflict(slug) do update set
 source_text=excluded.source_text,title=excluded.title,chapter=excluded.chapter,
 updated_at=now() where public.edubridge_ready_lessons.material_type='original_reference';